import typer
app = typer.Typer(help='A friendly CLI.')
@app.command()
def hello(name: str, loud: bool = typer.Option(False, '--loud','-l')):
    msg = f'HI {name.upper()}!' if loud else f'hi {name}'
    typer.echo(msg)
@app.command()
def add(a: int, b: int):
    typer.echo(a + b)
if __name__ == '__main__':
    app()
